import argparse
import os
import re
import sqlite3
import sys
from pathlib import Path

import psycopg
from psycopg import sql
from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parents[1]
SQLITE_PATH = ROOT / "database" / "agro_life_ai.db"
ENV_PATH = ROOT / ".env.local"


def stop(message):
    print(f"\nSTOP: {message}")
    raise SystemExit(1)


def quote_sqlite_identifier(name):
    return '"' + name.replace('"', '""') + '"'


def postgres_ddl(ddl):
    ddl = re.sub(
        r"\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b",
        "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
        ddl,
        flags=re.IGNORECASE,
    )
    ddl = re.sub(r"\bINTEGER\b", "BIGINT", ddl, flags=re.IGNORECASE)
    ddl = re.sub(r"\bREAL\b", "DOUBLE PRECISION", ddl, flags=re.IGNORECASE)
    return ddl


def main():
    parser = argparse.ArgumentParser(
        description="Safely migrate AGRO LIFE-AI from SQLite to Neon PostgreSQL."
    )
    parser.add_argument(
        "--execute",
        action="store_true",
        help="Actually create tables and copy records. Without this flag, only validate.",
    )
    args = parser.parse_args()

    print("=" * 65)
    print("AGRO LIFE-AI — SQLITE TO NEON MIGRATION")
    print("=" * 65)

    if not SQLITE_PATH.is_file():
        stop(f"SQLite database not found: {SQLITE_PATH}")
    if not ENV_PATH.is_file():
        stop("The .env.local file was not found.")

    load_dotenv(ENV_PATH, override=False)
    database_url = os.getenv("DATABASE_URL")
    if not database_url:
        stop("DATABASE_URL is missing. Check .env.local without printing its contents.")

    uri = SQLITE_PATH.resolve().as_uri() + "?mode=ro"

    try:
        with sqlite3.connect(uri, uri=True) as source:
            source.row_factory = sqlite3.Row
            integrity = source.execute("PRAGMA integrity_check").fetchone()[0]
            violations = source.execute("PRAGMA foreign_key_check").fetchall()
            if integrity != "ok":
                stop(f"SQLite integrity check failed: {integrity}")
            if violations:
                stop(f"SQLite has {len(violations)} foreign-key violations.")

            tables = [
                row["name"]
                for row in source.execute("""
                    SELECT name FROM sqlite_master
                    WHERE type='table' AND name NOT LIKE 'sqlite_%'
                    ORDER BY name
                """)
            ]
            if len(tables) != 15:
                stop(f"Expected 15 source tables, found {len(tables)}.")

            schema = {}
            rows_by_table = {}
            dependencies = {}
            counts = {}

            for table in tables:
                entry = source.execute(
                    "SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                    (table,),
                ).fetchone()
                if not entry or not entry[0]:
                    stop(f"Could not read schema for {table}.")
                schema[table] = entry[0]
                quoted = quote_sqlite_identifier(table)
                rows_by_table[table] = source.execute(
                    f"SELECT * FROM {quoted}"
                ).fetchall()
                counts[table] = len(rows_by_table[table])
                dependencies[table] = {
                    row["table"]
                    for row in source.execute(
                        f"PRAGMA foreign_key_list({quoted})"
                    )
                    if row["table"] != table
                }

            indexes = source.execute("""
                SELECT name, tbl_name, sql
                FROM sqlite_master
                WHERE type='index' AND sql IS NOT NULL
                ORDER BY name
            """).fetchall()

    except sqlite3.Error as exc:
        stop(f"Unable to read source database: {exc}")

    # Topologically order tables so referenced tables are created first.
    ordered = []
    pending = set(tables)
    while pending:
        ready = sorted(
            table for table in pending
            if dependencies[table].issubset(set(ordered))
        )
        if not ready:
            stop("Could not resolve table dependency order safely.")
        ordered.extend(ready)
        pending.difference_update(ready)

    print(f"\nSQLite integrity: {integrity}")
    print("SQLite foreign-key check: PASS")
    print(f"Source tables: {len(tables)}")
    print(f"Source records: {sum(counts.values())}")
    print(f"Destination mode: {'EXECUTE' if args.execute else 'DRY RUN'}")

    try:
        with psycopg.connect(
            database_url, connect_timeout=15, sslmode="require"
        ) as destination:
            with destination.cursor() as cur:
                cur.execute("""
                    SELECT table_name
                    FROM information_schema.tables
                    WHERE table_schema='public'
                      AND table_type='BASE TABLE'
                """)
                existing = [row[0] for row in cur.fetchall()]

                if existing:
                    stop(
                        "Neon already contains public tables. Nothing was migrated. "
                        "Review the destination before proceeding."
                    )

                if not args.execute:
                    print("\nNeon connection: PASS")
                    print("Destination tables: 0")
                    print("\nDRY RUN PASS — NO DATABASE CHANGES MADE.")
                    print("Review this script before running with --execute.")
                    return

                for table in ordered:
                    cur.execute(postgres_ddl(schema[table]))

                for table in ordered:
                    records = rows_by_table[table]
                    if not records:
                        continue

                    columns = list(records[0].keys())
                    insert_statement = sql.SQL("INSERT INTO {} ({}) VALUES ({})").format(
                        sql.Identifier(table),
                        sql.SQL(", ").join(map(sql.Identifier, columns)),
                        sql.SQL(", ").join(sql.Placeholder() for _ in columns),
                    )
                    cur.executemany(
                        insert_statement,
                        [tuple(record[column] for column in columns) for record in records],
                    )

                for index in indexes:
                    cur.execute(postgres_ddl(index["sql"]))

                # Align identity sequences with preserved source IDs.
                for table in ordered:
                    primary_keys = [
                        row[1]
                        for row in sqlite3.connect(
                            f"file:{SQLITE_PATH.as_posix()}?mode=ro", uri=True
                        ).execute(
                            f"PRAGMA table_info({quote_sqlite_identifier(table)})"
                        )
                        if row[5] > 0
                    ]
                    if len(primary_keys) == 1:
                        column = primary_keys[0]
                        cur.execute(
                            "SELECT pg_get_serial_sequence(%s, %s)",
                            (f"public.{table}", column),
                        )
                        sequence = cur.fetchone()[0]
                        if sequence:
                            cur.execute(
                                sql.SQL("""
                                    SELECT setval(%s::regclass, GREATEST(
                                        COALESCE((SELECT MAX({}) FROM {}), 1), 1
                                    ), EXISTS (SELECT 1 FROM {}))
                                """).format(
                                    sql.Identifier(column),
                                    sql.Identifier(table),
                                    sql.Identifier(table),
                                ),
                                (sequence,),
                            )

                for table in ordered:
                    cur.execute(
                        sql.SQL("SELECT COUNT(*) FROM {}").format(sql.Identifier(table))
                    )
                    actual = cur.fetchone()[0]
                    if actual != counts[table]:
                        raise RuntimeError(
                            f"Verification failed for {table}: "
                            f"expected {counts[table]}, got {actual}."
                        )

                cur.execute("SET CONSTRAINTS ALL IMMEDIATE")
                print("\nMIGRATION VERIFICATION")
                for table in ordered:
                    print(f"  PASS | {table}: {counts[table]} records")

                print(f"\nTOTAL RECORDS VERIFIED: {sum(counts.values())}")
                print("Migration transaction completed successfully.")

    except Exception as exc:
        stop(
            "Migration failed or was rolled back. "
            f"{type(exc).__name__}: {exc}"
        )


if __name__ == "__main__":
    main()
